from pathlib import Path
from copy import deepcopy
import re, shutil, json
from docx import Document
from docx.text.paragraph import Paragraph
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Pt, RGBColor

B=Path(__file__).parent
O=B.parents[1]/'output/documents'
backup=B/'before-release-012.docx'
if not backup.exists(): shutil.copy2(O/'GrowSpace_SRS_AR.docx',backup)
d=Document(backup)
ps=list(d.paragraphs)
latin=re.compile(r'([A-Za-z0-9][A-Za-z0-9_./:%+\-]*(?: [A-Za-z0-9][A-Za-z0-9_./:%+\-]*)*)')
def put(p,text,bold=None):
    old=p.runs[0] if p.runs else None
    size=old.font.size if old and old.font.size else Pt(11)
    strong=old.bold if old and bold is None else bool(bold)
    for x in list(p._p):
        if x.tag!=qn('w:pPr'):p._p.remove(x)
    for s in latin.split(text):
        if not s:continue
        r=p.add_run(s);r.font.name='Arial';r.font.size=size;r.bold=strong
        r.font.color.rgb=RGBColor.from_string('000000' if strong else '233447')
        rp=r._r.get_or_add_rPr()
        rf=rp.find(qn('w:rFonts'))
        for a in ['ascii','hAnsi','cs','eastAsia']:rf.set(qn('w:'+a),'Arial')
        rtl=OxmlElement('w:rtl');rtl.set(qn('w:val'),'0' if latin.fullmatch(s) else '1');rp.append(rtl)
        sz=OxmlElement('w:szCs');sz.set(qn('w:val'),str(int(size.pt*2)));rp.append(sz)
        if strong:rp.append(OxmlElement('w:bCs'))
    return p
def add(text,style=None,anchor=None):
    p=d.add_paragraph()
    p._p.append(deepcopy(ps[25]._p.get_or_add_pPr())) if p._p.find(qn('w:pPr')) is None else None
    if style:p.style=style
    p.paragraph_format.keep_with_next=bool(style)
    put(p,text,bool(style))
    if anchor is not None:anchor.addprevious(p._p)
    return p
def row(table,vals):
    tr=deepcopy(table.rows[-1]._tr);table._tbl.append(tr)
    for c,v in zip(table.rows[-1].cells,vals):
        put(c.paragraphs[0],v,False)
        for p in c.paragraphs[1:]:p._p.getparent().remove(p._p)
def setcell(table,r,c,text):put(table.cell(r,c).paragraphs[0],text,False)

